local function submitKey(key)
    key = M.cleanKey(key)
    if key == "" then
        Library:Notify({Title="⚠️ No se introdujo ninguna clave", Description="Por favor, introduce tu clave.", Time=3})
        return
    end
    Library:Notify({Title="🔑 Verificando", Description="Validando tu clave...", Time=2})

    -- NEW backend: validate the key + get this game's scripts in one call.
    local data, err = M.validateKeyNew(key)
    if type(data) ~= "table" then
        local msg = "Esa clave no es válida. Compruébala e inténtalo de nuevo."
        if err == "wrong_game" then
            msg = "Esta clave es para otro juego. Consigue una clave para este juego."
        elseif err == "network" or err == "no_request" then
            msg = "Error de red. Inténtalo de nuevo."
        end
        Library:Notify({Title="❌ Clave no válida", Description=msg, Time=5})
        return
    end

    local scripts = data.scripts or {}
    if #scripts == 0 then
        Library:Notify({Title="🔓 Clave válida", Description="Aún no hay scripts configurados para este juego.", Time=5})
        return
    end

    -- Valid — remember the key for next time, close this GUI, show the selector.
    M.saveKeyLocal(key)
    Library:Notify({
        Title = "🔓 Clave válida",
        Description = (#scripts == 1) and "Cargando script..." or "Elige un script...",
        Time = 3,
    })
    task.wait(0.4)
    pcall(function() Library:Unload() end)
    M.showSelector(scripts)
end

local function readKeyFromBox()
    local raw
    pcall(function()
        local holder = Options and Options.KeyInput and Options.KeyInput.Holder
        local box = holder and holder:FindFirstChildOfClass("TextBox")
        if box then raw = box.Text end
    end)
    local key = M.cleanKey(raw)
    if key == "" then key = M.cleanKey(Options and Options.KeyInput and Options.KeyInput.Value) end
    if key == "" then key = M.cleanKey(keyInputValue) end
    return key
end

